budgetFormulaDefinitions.formula_7:
=IFNA(
  SUM(
    FILTER(
      CASH_FLOW_PARAM_VALUES("company tax"),
      IFERROR(YEAR(R_MONTHS) = BUDGET_VALUE("_year"), FALSE),
      R_MONTHS < MONTH_START(TODAY())
    )
  ),
  0
)

